{"body":{"operationName":"PickupDaysByRegistrationNumber","query":"
query PickupDaysByRegistrationNumber($registrationNumber: String!) {
  pickupDays(filters: {registrationNumber: {eq: $registrationNumber}}) {
    data {
      attributes {
        registrationNumber
        address
        frequency
        wasteType
        frequencySeason
      }
    }
  }
}
","variables":{"registrationNumber":"1353013"}}}
